const express = require('express');
const http = require('http');
const WebSocket = require('ws');
const { createTradingGameDemo } = require('../adapter/tradingGameDemo');
const { createStateDiffBroadcast } = require('./stateDiffBroadcast');

const app = express();
const server = http.createServer(app);
const wss = new WebSocket.Server({ server });
const tradingDemo = createTradingGameDemo();
const broadcaster = createStateDiffBroadcast({ wss });

function publishWorldState() {
  const state = tradingDemo.getWorldState();
  broadcaster.broadcast(state);
}

class LocalDataLoader {
  constructor(options = {}) {
    this.dataPath = options.dataPath || DEFAULT_DATA_PATH;
    this.cache = null;
  }

  load() {
    if (!this.cache) {
      const raw = fs.readFileSync(this.dataPath, 'utf8');
      this.cache = JSON.parse(raw);
    }
    return this.cache;
  }

  getLatestPrice(symbol) {
    const rows = this.getHistory(symbol);
    return rows[rows.length - 1] || null;
  }
}

const AGENT_PROFILES = Object.freeze({
  'conservative-hedger': {
    role: '保守型',
    style: '先保本金，等待两个信号互相确认',
    commodityBias: 'gold',
    modelChain: ['DeepSeek-V4-Flash', 'Qwen3.6']
  },
  'aggressive-breakout': {
    role: '激进型',
    style: '动量和资讯共振时提前行动',
    commodityBias: 'soybean',
    modelChain: ['DeepSeek-V4-Flash', 'Qwen3.6']
  }
});

function buildDecision({ agentId, round, roundIndex }) {
  const profile = AGENT_PROFILES[agentId];
  const action = ACTIONS_BY_AGENT[agentId][roundIndex % ROUNDS.length];
  const commodity = COMMODITIES.find(item => item.id === profile.commodityBias);
  return {
    action,
    commodity: commodity.id,
    symbol: commodity.symbol,
    confidence: clampConfidence(58 + roundIndex * 5),
    exposure: action === 'BUY' ? '+1 做多' : action === 'SELL' ? '-1 减仓/反手' : '空仓观察',
    reason: `${profile.role}结合${round.regime}、价格和历史记忆后选择${action}`,
    evidence: [round.news[0], round.memory[0]]
  };
}

function scoreAgent({ agentId, rounds, completedTradeCount }) {
  const profile = AGENT_PROFILES[agentId];
  const commodity = COMMODITIES.find(item => item.id === profile.commodityBias);
  let equity = 0;
  let peak = 0;
  let maxDrawdown = 0;
  const trades = [];

  for (let i = 0; i < completedTradeCount; i += 1) {
    const action = ACTIONS_BY_AGENT[agentId][i % ROUNDS.length];
    const delta = calculateTradeScore({
      action,
      currentPrice: rounds[i].prices[commodity.id],
      nextPrice: rounds[i + 1].prices[commodity.id],
      exposureScale: EXPOSURE_SCALE_BY_AGENT[agentId]
    });
    equity = Number((equity + delta).toFixed(2));
    peak = Math.max(peak, equity);
    maxDrawdown = Math.max(maxDrawdown, Number((peak - equity).toFixed(2)));
    trades.push({ phase: i < TRAINING_TRADE_COUNT ? 'training' : 'test', action, scoreDelta: delta, equity });
  }
  return buildScoreSummary({ agentId, profile, trades, equity, maxDrawdown });
}

function renderPredictionReport(root, trading) {
  const analysis = trading.evaluation && trading.evaluation.analysis;
  root.innerHTML = `
    <section class="pr-metrics">${renderKeyMetrics(analysis)}</section>
    <section class="pr-bars">${renderScoreBars(analysis.scoreBars)}</section>
    <section class="pr-curve">${renderEquityCurve(analysis.topEquityCurve)}</section>
    <section class="pr-failures">${renderFailureCases(analysis.agentBreakdowns)}</section>
  `;
}

function buildMemory({ agentId, round, roundIndex }) {
  return {
    retrieved: round.memory.map((text, index) => ({
      id: `${agentId}-m${roundIndex}-${index}`,
      weight: Number((0.86 - index * 0.13).toFixed(2)),
      text
    })),
    lesson: `将${round.regime}与历史失败案例进行类比`
  };
}

function buildRepairPlan({ item, failures }) {
  const plans = [];
  if (failures.length > 0) plans.push('把最大失分回合加入记忆检索');
  if (item.maxDrawdown > 8) plans.push('降低连续同向开仓权重');
  if (item.testScore < item.trainingScore) plans.push('提高测试段样本权重');
  return plans.join('；');
}
